-- ── Psyko Seven ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Psyko Seven',
        'dominican',
        '2013 — Ventura Cigar Company, Californie',
        'République dominicaine — la maison ne nomme pas sa fabrique ; version Nicaragua chez Agrotabacos (famille Ortez), Condega',
        'venturacigar.com « Psyko Seven - Ventura Cigar Company » (2 octobre 2026 : mélange de sept tabacs de six pays, façonné en République dominicaine, dit la maison, sans usine nommée ; quatre mélanges, Natural de force douce à moyenne, Maduro de force moyenne, Connecticut de force douce et Nicaragua de profil plein ; tailles Corona 5 1/2 x 46, Toro 6 1/4 x 48, Robusto 5 1/2 x 50, Gordito 4 x 58 et Gordo 6 x 60 selon les mélanges) ; venturacigar.com « Ventura Cigar Company » (2 octobre 2026 : marques Cuban Rejects, Cuban Rounds, Hugo, Psyko Seven et Slaughterhouse ; actualités de 2018 et 2019 seulement) ; psyko7cigars.com « Psyko Seven - Cigars » (2 octobre 2026, copyright 2026 : Natural à cape hybride dominicaine, liant Sumatra du Mexique, tripe de plusieurs pays, douce à moyenne, cinq vitolas de la Corona 5 1/2 x 46 au Gordo 6 x 60 ; Maduro à cape San Andrés, liant équatorien 151, tripe de cinq pays, moyen, décrit de force moyenne à pleine, quatre vitolas ; Connecticut à cape Connecticut d''Équateur, liant San Vicente dominicain, doux, trois vitolas ; Nicaragua à cape Desflorada Connecticut de 2007, liant du Nicaragua, tripe du Nicaragua (Condega, Estelí, Jalapa), de profil plein, décrit de corps moyen à plein, Toro 6 x 50, Robusto 5 1/2 x 50 et Gordo 6 x 60 ; Psykorillo 3 1/4 x 20, cape maduro, force pleine) ; kretek.com « Psyko Seven » (2 octobre 2026, copyright 2026 : Psyko Seven, ligne premium de Kretek International, façonnée en République dominicaine ; quatre mélanges Natural, Maduro, Connecticut et Nicaragua ; Connecticut à cape et liant Connecticut d''Équateur ; Robusto 5 1/2 x 50, Toro 6 1/4 x 48, Gordo 6 x 60) ; cigarcentury.com « Psyko Seven » (2 octobre 2026, détaillant : seize références Psyko Seven en Connecticut, Maduro et Natural, dites venues de République dominicaine ; nom dit dû au mélange de sept tabacs du monde en tripe) ; kohnhed.com « PSyKo SEVEN by Ventura Cigar Co. | Cigar Review » (19 mai 2014 : usine en République dominicaine ; débuts du cigare à l''IPCPR 2013) ; blindmanspuff.com « Blind Cigar Review: Ventura Cigars | PSyKo Seven Robusto » (20 janvier 2014 : Robusto Natural, pays d''origine République dominicaine, usine E. León Jimenes Tabacalera, mélangeur Henke Kelner) ; cigardojo.com « PSyKo SEVEN MADuRo Cigar Review » (7 juillet 2015 : maduro lancé par Ventura Cigar Company, cape San Andrés mexicaine, usine Occidental Cigar Corp, Inc., République dominicaine) ; cigardojo.com « Ventura Cigar Company Announces PSyKo SEVEN Nicaragua » (14 mars 2019 : cinquième cigare de la marque, après les mélanges Maduro, Connecticut et Maduro Psykorillos ; Indiana Ortez, fille du mélangeur Omar Ortez et rouleuse de troisième génération au Nicaragua, a mené le projet à la fabrique Agrotabacos de Condega ; cape Desflorada de 2007 ; Robusto, Toro et Gordo en boîtes de vingt ; collaboration précédente avec Ventura pour Fathers, Friends, and Fire au printemps 2018) ; cigaraficionado.com « Q&A: Indiana Ortez, Agrotabacos » (5 février 2019 : Agrotabacos née en 1995 comme entreprise familiale, cigares roulés à la main avec du tabac de trois régions du Nicaragua ; Indiana Ortez, responsable du contrôle qualité et directrice marketing d''Agrotabacos ; 40 % de la production pour les marques de la famille, 60 % pour des tiers, dont Kretek International) ; cigaraficionado.com « The New Old Guys: Ventura Cigar Company » (15 juin 2012 : Ventura, filiale de Kretek International Group Inc., société de Moorpark, en Californie ; le docteur Mark Cassar, président-directeur général de Kretek, ancien chiropracteur entré dans l''entreprise familiale ; Kretek a monté Ventura, nommée d''après le comté de Californie où vit la famille Cassar ; premières marques Pura Sangre et Estilo Cubano ; débuts de Ventura à l''IPCPR l''été précédent) ; cigaraficionado.com « Ventura Cigar Co. Shifts to Standalone Business Model » (4 janvier 2019 : Ventura, d''abord division de Phillips & King International, devient une unité autonome sous Kretek International au 1er janvier ; Michael Giannini, directeur général de Ventura Cigars ; marques Project 805, Psyko Seven, Archetype Dreamstate et Archetype Axis Mundi) ; cigar-coop.com « PCA 2025 - The Big Board » et « PCA 2026 - The Big Board » (pages lues le 2 octobre 2026 : ni Ventura ni Psyko Seven au tableau des exposants)',
        NULL,
        'Psyko Seven est une marque de Ventura Cigar Company, société californienne que Kretek International a montée, dit un article de juin 2012 ; Kretek, société de Moorpark, en Californie, a pour président-directeur général en 2012 le docteur Mark Cassar, ancien chiropracteur entré dans l''entreprise familiale, et Ventura doit son nom au comté californien de la famille Cassar. Kohnhed (19 mai 2014) écrit que la marque a fait ses débuts à l''IPCPR 2013.

La maison décrit Psyko Seven comme un mélange de sept tabacs de six pays, façonné en République dominicaine, sans nommer l''usine ; Century Premium Cigars dit le nom dû à ces sept tabacs. D''anciens comptes rendus nomment des usines dominicaines : E. León Jimenes Tabacalera pour le Robusto Natural (Blind Man''s Puff, janvier 2014) et Occidental Cigar Corp pour le Maduro (Cigar Dojo, juillet 2015). La version Nicaragua, cinquième cigare de la marque, est annoncée le 14 mars 2019 : Indiana Ortez, fille du mélangeur Omar Ortez, a mené le projet, roulé à la fabrique Agrotabacos, à Condega, dit Cigar Dojo. Indiana Ortez dit en février 2019 qu''Agrotabacos, née en 1995 comme entreprise familiale, roule aussi pour des tiers, dont Kretek International.

En octobre 2026, les sites de la marque et de Kretek International, tous deux sous copyright 2026, présentent quatre mélanges, Natural, Maduro, Connecticut et Nicaragua, Kretek écrivant la marque façonnée en République dominicaine, et Century Premium Cigars liste seize références. Sa dernière sortie est la version Nicaragua, en mars 2019.',
        '[{"name":"Natural","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Hybride dominicain","vitolas":[],"story":"Cape hybride dominicaine, liant Sumatra du Mexique, tripe de plusieurs pays, force douce à moyenne, dit la maison, en cinq vitolas, de la Corona (5 1/2 x 46) au Gordo (6 x 60)."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Cape San Andrés mexicaine, liant équatorien 151, tripe de cinq pays, force moyenne, dit la maison, qui la décrit aussi de force moyenne à pleine ; quatre vitolas, de la Corona (5 1/2 x 46) au Gordo (6 x 60)."},{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Équateur)","vitolas":[],"story":"Cape Connecticut d''Équateur, liant San Vicente dominicain, tripe de plusieurs pays, force douce, dit la maison, en trois vitolas, Robusto (5 1/2 x 50), Toro (6 1/4 x 48) et Gordo (6 x 60)."},{"name":"Nicaragua","color":"#C9A96E","force":"Medium-Full","wrapper":"Desflorada Connecticut (2007)","vitolas":[],"story":"Cape Desflorada Connecticut de 2007, liant et tripe du Nicaragua (Condega, Estelí, Jalapa), de corps moyen à plein dans la description de la maison et de profil plein dans sa fiche technique, en Robusto (5 1/2 x 50), Toro et Gordo (6 x 60) ; roulée à Agrotabacos, à Condega, avec Indiana Ortez, dit Cigar Dojo."}]',
        'Psyko Seven is a brand of Ventura Cigar Company, a Californian company that Kretek International set up, says an article of June 2012; Kretek, a company in Moorpark, California, has as its chairman and chief executive in 2012 Dr Mark Cassar, a former chiropractor who joined the family business, and Ventura takes its name from the Californian county where the Cassar family lives. Kohnhed (19 May 2014) writes that the brand made its debut at the IPCPR 2013.

The house describes Psyko Seven as a blend of seven tobaccos from six countries, made in the Dominican Republic, without naming the factory; Century Premium Cigars says the name comes from those seven tobaccos. Older accounts name Dominican factories: E. León Jimenes Tabacalera for the Robusto Natural (Blind Man''s Puff, January 2014) and Occidental Cigar Corp for the Maduro (Cigar Dojo, July 2015). The Nicaragua version, the brand''s fifth cigar, is announced on 14 March 2019: Indiana Ortez, daughter of the blender Omar Ortez, led the project, which was rolled at the Agrotabacos factory, in Condega, says Cigar Dojo. Indiana Ortez says in February 2019 that Agrotabacos, born in 1995 as a family business, also rolls for third parties, including Kretek International.

In October 2026, the websites of the brand and of Kretek International, both with a 2026 copyright, present four blends, Natural, Maduro, Connecticut and Nicaragua, Kretek writing the brand as made in the Dominican Republic, and Century Premium Cigars lists sixteen items. Its last release is the Nicaragua version, in March 2019.',
        '[{"name":"Natural","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Dominican hybrid","vitolas":[],"story":"Dominican hybrid wrapper, Sumatra binder from Mexico, filler from several countries, mild-to-medium strength, says the house, in five vitolas, from the Corona (5 1/2 x 46) to the Gordo (6 x 60)."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Mexican San Andrés wrapper, Ecuadorian 151 binder, filler from five countries, medium strength, says the house, which also describes it as medium-to-full strength; four vitolas, from the Corona (5 1/2 x 46) to the Gordo (6 x 60)."},{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Connecticut wrapper from Ecuador, Dominican San Vicente binder, filler from several countries, mild strength, says the house, in three vitolas, Robusto (5 1/2 x 50), Toro (6 1/4 x 48) and Gordo (6 x 60)."},{"name":"Nicaragua","color":"#C9A96E","force":"Medium-Full","wrapper":"Desflorada Connecticut (2007)","vitolas":[],"story":"A 2007 Desflorada Connecticut wrapper, binder and filler from Nicaragua (Condega, Estelí, Jalapa), medium-to-full in body in the house''s description and full in profile in its technical sheet, in Robusto (5 1/2 x 50), Toro and Gordo (6 x 60); rolled at Agrotabacos, in Condega, with Indiana Ortez, says Cigar Dojo."}]',
        'Psyko Seven es una marca de Ventura Cigar Company, empresa californiana que Kretek International montó, dice un artículo de junio de 2012; Kretek, empresa de Moorpark, en California, tiene como presidente y director general en 2012 al doctor Mark Cassar, antiguo quiropráctico que se incorporó a la empresa familiar, y Ventura debe su nombre al condado de California donde vive la familia Cassar. Kohnhed (19 de mayo de 2014) escribe que la marca debutó en el IPCPR 2013.

La casa describe Psyko Seven como una mezcla de siete tabacos de seis países, elaborada en República Dominicana, sin nombrar la fábrica; Century Premium Cigars dice que el nombre se debe a esos siete tabacos. Textos antiguos nombran fábricas dominicanas: E. León Jimenes Tabacalera para el Robusto Natural (Blind Man''s Puff, enero de 2014) y Occidental Cigar Corp para el Maduro (Cigar Dojo, julio de 2015). La versión Nicaragua, quinto puro de la marca, se anuncia el 14 de marzo de 2019: Indiana Ortez, hija del mezclador Omar Ortez, dirigió el proyecto, liado en la fábrica Agrotabacos, en Condega, dice Cigar Dojo. Indiana Ortez dice en febrero de 2019 que Agrotabacos, nacida en 1995 como empresa familiar, también lía para terceros, entre ellos Kretek International.

En octubre de 2026, los sitios de la marca y de Kretek International, ambos con copyright 2026, presentan cuatro mezclas, Natural, Maduro, Connecticut y Nicaragua, y Kretek escribe que la marca se elabora en República Dominicana; Century Premium Cigars enumera dieciséis referencias. Su último lanzamiento es la versión Nicaragua, en marzo de 2019.',
        '[{"name":"Natural","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Híbrido dominicano","vitolas":[],"story":"Capa híbrida dominicana, capote Sumatra de México, tripa de varios países, fuerza suave a media, dice la casa, en cinco vitolas, de la Corona (5 1/2 x 46) al Gordo (6 x 60)."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (México)","vitolas":[],"story":"Capa San Andrés mexicana, capote ecuatoriano 151, tripa de cinco países, fuerza media, dice la casa, que también la describe de fuerza media a plena; cuatro vitolas, de la Corona (5 1/2 x 46) al Gordo (6 x 60)."},{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Capa Connecticut de Ecuador, capote San Vicente dominicano, tripa de varios países, fuerza suave, dice la casa, en tres vitolas, Robusto (5 1/2 x 50), Toro (6 1/4 x 48) y Gordo (6 x 60)."},{"name":"Nicaragua","color":"#C9A96E","force":"Medium-Full","wrapper":"Desflorada Connecticut (2007)","vitolas":[],"story":"Capa Desflorada Connecticut de 2007, capote y tripa de Nicaragua (Condega, Estelí, Jalapa), de cuerpo medio a pleno en la descripción de la casa y de perfil pleno en su ficha técnica, en Robusto (5 1/2 x 50), Toro y Gordo (6 x 60); liada en Agrotabacos, en Condega, con Indiana Ortez, dice Cigar Dojo."}]',
        'Psyko Seven ist eine Marke von Ventura Cigar Company, einem kalifornischen Unternehmen, das Kretek International aufgebaut hat, so ein Artikel vom Juni 2012; Kretek, ein Unternehmen in Moorpark in Kalifornien, hat 2012 Dr. Mark Cassar, einen ehemaligen Chiropraktiker, der in das Familienunternehmen eingetreten ist, als Vorsitzenden und Geschäftsführer, und Ventura verdankt seinen Namen dem kalifornischen County, in dem die Familie Cassar lebt. Kohnhed (19. Mai 2014) schreibt, die Marke habe ihr Debüt auf der IPCPR 2013 gegeben.

Das Haus beschreibt Psyko Seven als Mischung aus sieben Tabaken aus sechs Ländern, in der Dominikanischen Republik hergestellt, ohne die Fabrik zu nennen; Century Premium Cigars führt den Namen auf diese sieben Tabake zurück. Ältere Berichte nennen dominikanische Fabriken: E. León Jimenes Tabacalera für den Robusto Natural (Blind Man''s Puff, Januar 2014) und Occidental Cigar Corp für den Maduro (Cigar Dojo, Juli 2015). Die Version Nicaragua, die fünfte Zigarre der Marke, wird am 14. März 2019 angekündigt: Indiana Ortez, Tochter des Blenders Omar Ortez, leitete das Projekt, das in der Fabrik Agrotabacos in Condega gerollt wurde, so Cigar Dojo. Indiana Ortez sagt im Februar 2019, dass Agrotabacos, 1995 als Familienunternehmen entstanden, auch für Dritte rollt, darunter Kretek International.

Im Oktober 2026 stellen die Websites der Marke und von Kretek International, beide mit Copyright 2026, vier Mischungen vor, Natural, Maduro, Connecticut und Nicaragua, wobei Kretek die Marke in der Dominikanischen Republik hergestellt angibt; Century Premium Cigars listet sechzehn Artikel. Ihre letzte Veröffentlichung ist die Version Nicaragua im März 2019.',
        '[{"name":"Natural","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Dominikanischer Hybrid","vitolas":[],"story":"Dominikanisches Hybrid-Deckblatt, Umblatt Sumatra aus Mexiko, Einlage aus mehreren Ländern, milde bis mittlere Stärke, so das Haus, in fünf Vitolas, von der Corona (5 1/2 x 46) bis zum Gordo (6 x 60)."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Mexikanisches Deckblatt San Andrés, ecuadorianisches Umblatt 151, Einlage aus fünf Ländern, mittlere Stärke, so das Haus, das sie auch mit mittlerer bis voller Stärke beschreibt; vier Vitolas, von der Corona (5 1/2 x 46) bis zum Gordo (6 x 60)."},{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Deckblatt Connecticut aus Ecuador, dominikanisches Umblatt San Vicente, Einlage aus mehreren Ländern, milde Stärke, so das Haus, in drei Vitolas, Robusto (5 1/2 x 50), Toro (6 1/4 x 48) und Gordo (6 x 60)."},{"name":"Nicaragua","color":"#C9A96E","force":"Medium-Full","wrapper":"Desflorada Connecticut (2007)","vitolas":[],"story":"Deckblatt Desflorada Connecticut von 2007, Umblatt und Einlage aus Nicaragua (Condega, Estelí, Jalapa), in der Beschreibung des Hauses mit mittlerem bis vollem Körper und im Datenblatt mit vollem Profil, als Robusto (5 1/2 x 50), Toro und Gordo (6 x 60); bei Agrotabacos in Condega gerollt, mit Indiana Ortez, so Cigar Dojo."}]',
        'Psyko Seven是Ventura Cigar Company的品牌，这是一家加利福尼亚州公司，据2012年6月的一篇文章称，由Kretek International组建；Kretek是位于加利福尼亚州穆尔帕克的公司，2012年的董事长兼首席执行官是Mark Cassar医生，他是前脊椎按摩师，后加入家族企业，Ventura的名称则来自Cassar家族居住的加利福尼亚州的县。Kohnhed（2014年5月19日）写道，该品牌于2013年IPCPR首次亮相。

品牌方将Psyko Seven描述为由六个国家的七种烟叶调配而成、在多米尼加共和国制作的拼配，但未点出工厂名称；Century Premium Cigars称其名称源于这七种烟叶。早期的报道点名了多米尼加的工厂：Blind Man''s Puff（2014年1月）称Robusto Natural出自E. León Jimenes Tabacalera，Cigar Dojo（2015年7月）称Maduro出自Occidental Cigar Corp。Nicaragua版本是该品牌的第五款雪茄，于2019年3月14日宣布：Indiana Ortez是调配师Omar Ortez的女儿，主导了该项目，据Cigar Dojo称，该雪茄在孔德加的Agrotabacos工厂卷制。Indiana Ortez在2019年2月称，Agrotabacos于1995年作为家族企业创立，也为第三方卷制雪茄，其中包括Kretek International。

2026年10月，该品牌与Kretek International的网站均标注2026年版权，介绍了四种拼配：Natural、Maduro、Connecticut与Nicaragua，其中Kretek写明该品牌在多米尼加共和国制作；Century Premium Cigars列出十六个品项。该品牌的末次发布是2019年3月的Nicaragua版本。',
        '[{"name":"Natural","color":"#8B5A2B","force":"Mild-Medium","wrapper":"多米尼加杂交品种","vitolas":[],"story":"多米尼加杂交品种茄衣，茄套为墨西哥Sumatra，茄芯来自多个国家，力度温和至中等，据品牌方称，有五种规格，从Corona（5 1/2 x 46）到Gordo（6 x 60）。"},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"墨西哥San Andrés茄衣，厄瓜多尔151茄套，茄芯来自五个国家，力度中等，据品牌方称，品牌方也将其描述为力度中等至饱满；有四种规格，从Corona（5 1/2 x 46）到Gordo（6 x 60）。"},{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut（厄瓜多尔）","vitolas":[],"story":"厄瓜多尔Connecticut茄衣，多米尼加San Vicente茄套，茄芯来自多个国家，力度温和，据品牌方称，有三种规格，即Robusto（5 1/2 x 50）、Toro（6 1/4 x 48）与Gordo（6 x 60）。"},{"name":"Nicaragua","color":"#C9A96E","force":"Medium-Full","wrapper":"Desflorada Connecticut（2007）","vitolas":[],"story":"2007年的Desflorada Connecticut茄衣，茄套与茄芯来自尼加拉瓜（孔德加、埃斯特利、哈拉帕），据品牌方的描述烟体中等至饱满，据其技术说明风格饱满；有Robusto（5 1/2 x 50）、Toro与Gordo（6 x 60）；据Cigar Dojo称，在孔德加的Agrotabacos与Indiana Ortez合作卷制。"}]',
        'Psyko Seven علامة تابعة لـVentura Cigar Company، وهي شركة كاليفورنية أنشأتها Kretek International، بحسب مقال من يونيو 2012؛ وKretek شركة في مووربارك بكاليفورنيا، رئيس مجلس إدارتها والمدير العام فيها عام 2012 هو الدكتور Mark Cassar، وهو أخصائي سابق في تقويم العمود الفقري انضم إلى الشركة العائلية، وتدين Ventura باسمها إلى المقاطعة الكاليفورنية التي تقيم فيها عائلة Cassar. ويكتب Kohnhed (19 مايو 2014) أن العلامة ظهرت لأول مرة في IPCPR 2013.

تصف الدار Psyko Seven بأنها خلطة من سبعة أنواع تبغ من ستة بلدان، صُنعت في جمهورية الدومينيكان، دون أن تسمّي المصنع؛ وتقول Century Premium Cigars إن الاسم يعود إلى هذه الأنواع السبعة من التبغ. وتسمّي تقارير قديمة مصانع دومينيكية: E. León Jimenes Tabacalera لسيجار Robusto Natural (Blind Man''s Puff، يناير 2014) وOccidental Cigar Corp لـMaduro (Cigar Dojo، يوليو 2015). أما نسخة Nicaragua، خامس سيجار للعلامة، فأُعلن عنها في 14 مارس 2019: قادت Indiana Ortez، ابنة خبير المزج Omar Ortez، المشروع الذي لُفّ في مصنع Agrotabacos في كونديغا، بحسب Cigar Dojo. وتقول Indiana Ortez في فبراير 2019 إن Agrotabacos، التي وُلدت عام 1995 كشركة عائلية، تلف أيضًا لحساب أطراف ثالثة، منها Kretek International.

وفي أكتوبر 2026، يعرض موقع العلامة وموقع Kretek International، وكلاهما بحقوق نشر 2026، أربع خلطات هي Natural وMaduro وConnecticut وNicaragua، وتكتب Kretek أن العلامة تُصنع في جمهورية الدومينيكان، وتدرج Century Premium Cigars ستة عشر صنفًا. وآخر إصدار لها هو نسخة Nicaragua في مارس 2019.',
        '[{"name":"Natural","color":"#8B5A2B","force":"Mild-Medium","wrapper":"هجين دومينيكي","vitolas":[],"story":"غلاف هجين دومينيكي، ورباط Sumatra من المكسيك، وحشوة من عدة بلدان، بقوة من خفيفة إلى متوسطة، بحسب الدار، في خمسة مقاسات، من Corona (5 1/2 x 46) إلى Gordo (6 x 60)."},{"name":"Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"غلاف San Andrés مكسيكي، ورباط إكوادوري 151، وحشوة من خمسة بلدان، بقوة متوسطة، بحسب الدار التي تصفها أيضًا بقوة من متوسطة إلى كاملة؛ في أربعة مقاسات، من Corona (5 1/2 x 46) إلى Gordo (6 x 60)."},{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (الإكوادور)","vitolas":[],"story":"غلاف Connecticut من الإكوادور، ورباط San Vicente دومينيكي، وحشوة من عدة بلدان، بقوة خفيفة، بحسب الدار، في ثلاثة مقاسات هي Robusto (5 1/2 x 50) وToro (6 1/4 x 48) وGordo (6 x 60)."},{"name":"Nicaragua","color":"#C9A96E","force":"Medium-Full","wrapper":"Desflorada Connecticut (2007)","vitolas":[],"story":"غلاف Desflorada Connecticut من عام 2007، ورباط وحشوة من نيكاراغوا (كونديغا وإستيلي وخالابا)، بقوام من متوسط إلى ممتلئ بحسب وصف الدار وبطابع ممتلئ بحسب بطاقتها التقنية، في Robusto (5 1/2 x 50) وToro وGordo (6 x 60)؛ تُلَفّ في Agrotabacos في كونديغا، مع Indiana Ortez، بحسب Cigar Dojo."}]')
