  (NULL,'migration 247','systeme','recensement_8_fiches','marque',0,
   'nicaragua : Casa de Torres, Charatan, Dapper, Latitude Zero, League of Fat Bastards, Loaisiga, Ohana, Warfighter Tobacco'),
