SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Casa de Torres','Charatan','Dapper','Latitude Zero','League of Fat Bastards','Loaisiga','Ohana','Psyko Seven','Warfighter Tobacco')) = 9 AS fiches,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Casa de Torres"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Charatan"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Dapper"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Latitude Zero"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"League of Fat Bastards"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Loaisiga"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Ohana"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Warfighter Tobacco"') FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Psyko Seven"') FROM `producer_countries` WHERE `id` = 'dominican') AS dominican_annonce,
  (SELECT COUNT(*) FROM `translation_status` WHERE `entite` = 'brands' AND `entite_id` IN ('Casa de Torres','Charatan','Dapper','Latitude Zero','League of Fat Bastards','Loaisiga','Ohana','Psyko Seven','Warfighter Tobacco')) = 90 AS sceaux,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 247') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
